interface Node { render(): string }
class Leaf implements Node {
  constructor(private name: string) {}
  render() { return this.name }
}
class Container implements Node {
  constructor(public children: Node[] = []) {}
  render() { return this.children.map(c => c.render()).join(',') }
}

interface Item { add(child: Item): void; render(): string }
class Leaf implements Item {
  render() { return 'leaf' }
  add(child: Item) { throw new Error('cannot add to leaf') }
}
function attach(parent: Item, child: Item) {
  if ((parent as any).add) parent.add(child)
  else throw new Error('not a container')
}

// Version A
interface Node { render(): string; children?: Node[] }
class LeafA implements Node {
  constructor(private name: string) {}
  render() { return this.name }
}
class ContainerA implements Node {
  constructor(public children: Node[] = []) {}
  render() { return this.children.map(c => c.render()).join(',') }
}

// Version B
interface Widget { render(): string }
class LeafB implements Widget {
  constructor(private name: string) {}
  render() { return this.name }
}
class ContainerB implements Widget {
  private children: Widget[] = []
  add(child: Widget) { this.children.push(child) }
  render() { return this.children.map(c => c.render()).join(',') }
}
